components.css:
.ds-button {display: inline-flex; justify-content: center; align-items: center; gap: 12px; min-height: 52px; padding: 13px 24px; background: var(--green); color: white; border-radius: 999px; font-size: 14px; font-weight: 600; transition: background 180ms ease, border-color 180ms ease;}
.ds-button:hover {background: #245c4c;}
.ds-button.ds-secondary {background: transparent; color: var(--green); border: 1px solid #bccaba;}
.ds-button.ds-secondary:hover {background: var(--sage);}
.ds-button.ds-light {background: var(--lime); color: var(--green);}
.ds-button.ds-light:hover {background: #e3f3bc;}
.ds-button { font-family: DM Sans, sans-serif; line-height: 1.6; text-decoration: none; }
.ds-button:focus-visible, .ds-nav a:focus-visible, .ds-faq summary:focus-visible { outline: 3px solid #a96712; outline-offset: 6px; }
@media (max-width: 700px) { .ds-button { font-size: 13px; min-height: 48px; padding: 12px 19px; } }
@media (prefers-reduced-motion: reduce) { .ds-button { transition: none; } }

