.ds-faq details {border-bottom: 1px solid var(--line); padding: 22px 0;}
.ds-faq summary {cursor: pointer; display: flex; justify-content: space-between; align-items: center; gap: 24px; font-size: 17px; font-weight: 600; list-style: none; min-height: 30px;}
.ds-faq summary::-webkit-details-marker {display: none;}
.ds-faq summary .ds-icon {transition: transform 280ms cubic-bezier(0.16,1,0.3,1);}
.ds-faq details[open] summary .ds-icon {transform: rotate(45deg);}
.ds-faq details p {font-size: 15px; padding-top: 15px; max-width: 62ch;} .ds-faq {font-family: DM Sans, sans-serif; color: var(--ink); line-height: 1.6;} .ds-faq p {margin: 0; color: var(--muted);} .ds-icon {width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;flex-shrink:0;} .ds-button:focus-visible, .ds-nav a:focus-visible, .ds-faq summary:focus-visible { outline: 3px solid #a96712; outline-offset: 6px; } @media (prefers-reduced-motion: reduce) {.ds-faq .ds-icon {transition:none;}}
